python3 <<'PY'
import json
from pathlib import Path

feed = json.loads(Path('/workspace/etoroview/public/trading-qa.json').read_text())
dist = Path('/workspace/etoroview/dist/trading-qa.json')
audit_lines = [json.loads(l) for l in Path('/workspace/momentum_audit/2026-09-11.jsonl').read_text().splitlines() if l.strip()]
fb = json.loads(Path('/workspace/trading-lessons/momentum/2026-09-11/daily_feedback.json').read_text())
idx = json.loads(Path('/workspace/trading-lessons/2026-09-06/index.json').read_text())
src_dir = Path('/workspace/trading-lessons/2026-09-06')

classic = next(p for p in feed['portfolios'] if p['key']=='classic')
mom = next(p for p in feed['portfolios'] if p['key']=='momentum')

fails=[]
notes=[]

print('asOf', feed.get('asOf'))
print('dual-write', dist.exists() and dist.read_bytes()==Path('/workspace/etoroview/public/trading-qa.json').read_bytes())

# Classic structure
cids=[c.get('caseId') for c in classic.get('classicCases') or []]
print('classicCases', cids)
if len(cids)!=len(set(cids)):
  fails.append('classicCases still have duplicate caseIds')
expected={'20260905-ETH-sell-close','20260906-daily_brief-afternoon-hold','20260908-IGV-sell-close-filled'}
if set(cids)!=expected:
  fails.append(f'classicCases set mismatch: {set(cids)} vs {expected}')
# no index-like in classicCases
for i,c in enumerate(classic['classicCases']):
  if 'KEEP' in c and 'cases' in c and not c.get('caseId'):
    fails.append(f'index-like still in classicCases[{i}]')
  if not c.get('caseId'):
    fails.append(f'classicCases[{i}] missing caseId')

# days from index
if len(classic.get('days') or [])!=1:
  fails.append(f'classic days expected 1 got {len(classic.get("days") or [])}')
else:
  day=classic['days'][0]
  # compare KEEP/AVOID to index
  for key in ['KEEP','AVOID','WATCH','forwardHook','cases','portfolio']:
    if key in idx:
      if day.get(key)!=idx.get(key) and key!='asOf':
        # allow asOf refresh on day
        if day.get(key)!=idx.get(key):
          fails.append(f'classic days[0].{key} != index')
          print('DIFF', key)
          print(' day', day.get(key))
          print(' idx', idx.get(key))
  print('classic day keys', sorted(day.keys()))
  print('classic day KEEP count', len(day.get('KEEP') or day.get('lessons') or []))

# truth notes / mirrors
if classic.get('mirrorId')!=11368142:
  fails.append(f'classic mirrorId {classic.get("mirrorId")}')
if 'keys' in (classic.get('truthNote') or '').lower() and 'never' not in (classic.get('truthNote') or '').lower():
  notes.append('classic truthNote check')
if mom.get('mirrorId')!=11630170:
  fails.append(f'momentum mirrorId missing/wrong: {mom.get("mirrorId")}')
if '8000' not in (mom.get('truthNote') or ''):
  fails.append('momentum truthNote missing 8000')

# case content vs files
for cid in expected:
  src=None
  for p in src_dir.glob('*.json'):
    if p.name=='index.json': continue
    d=json.loads(p.read_text())
    if d.get('caseId')==cid:
      src=d; break
  feed_case=next(c for c in classic['classicCases'] if c.get('caseId')==cid)
  if src is None:
    fails.append(f'no source for {cid}')
    continue
  # compare core fields
  for path in [('position','orderId'),('position','positionId'),('position','netProfit'),('position','closeRate'),('caseScore',),('portfolio',)]:
    def dig(o,path):
      cur=o
      for k in path:
        if not isinstance(cur,dict): return None
        cur=cur.get(k)
      return cur
    if dig(feed_case,path)!=dig(src,path):
      fails.append(f'{cid} {".".join(path)} mismatch feed={dig(feed_case,path)} src={dig(src,path)}')

# Momentum
if mom.get('auditRows')!=audit_lines:
  fails.append('momentum auditRows != jsonl')
audit_actions=[r for r in audit_lines if r.get('event')=='ACTION']
if mom.get('actions')!=audit_actions:
  fails.append('momentum actions != audit ACTION rows')
if not mom.get('days') or mom['days'][0]!=fb:
  fails.append('momentum days[0] != daily_feedback.json')

print('\nFAILS:')
for f in fails: print('-', f)
print('NOTES:', notes)
print('VERDICT', 'FAIL' if fails else 'PASS')
# show classic day briefly
if classic.get('days'):
  d=classic['days'][0]
  print('classic day portfolio', d.get('portfolio'), 'cases', d.get('cases'), 'KEEP n', len(d.get('KEEP') or []), 'AVOID n', len(d.get('AVOID') or []))
PY
